starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 3.0"
    }
  }
}

starter.variables.tf:
variable "network_name" {
  description = "Input variable network_name."
  type        = string
  default     = "app-net"
}

starter.main.tf:
provider "docker" {
  host = var.docker_host
}

